// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint256 salt, address player) public {
        vm.assume(player != address(0));
        vm.assume(player != address(c));

        // The settlement block (lock block + 1) has not been mined when we settle,
        // so blockhash(target) == bytes32(0) and the correct answer is fixed:
        bytes32 correctAnswer = keccak256(abi.encodePacked(bytes32(0)));

        // Player locks in the CORRECT answer hash (deposit of 1 ether -> balance 2 ether).
        vm.deal(player, 1 ether);
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(correctAnswer);

        // Roll past the settlement target block (any distance works; its hash is 0).
        uint256 lockBlock = block.number - 1; // lock happened this txn at previous-numbered block + 1
        vm.roll(block.number + 1 + (salt % 10));

        bool ok;
        vm.prank(player);
        try c.settle() { ok = true; } catch { ok = false; }

        // Reference rule: a correct guess always wins and the 2 ether prize is
        // transferred out, leaving the contract empty. The mutant never stores the
        // guess (stays bytes32(0)), the answer never matches, no payout occurs and
        // the contract keeps the 2 ether.
        assertTrue(ok && address(c).balance == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint256 offset, address actor) public {
        offset = bound(offset, 1, 100);
        vm.assume(actor != address(0));

        // Choose a target block, then learn its (deterministic) blockhash while it is
        // within the 256-block window, so the settlement answer is computable.
        vm.roll(offset);
        uint256 target = block.number + 1;
        vm.roll(target + 1);
        bytes32 bh = blockhash(target);
        bytes32 winningHash = keccak256(abi.encodePacked(bh));

        // Roll back so locking in records target as the guess block.
        vm.roll(target - 1);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(winningHash);

        // Fund the contract so the 2-ether payout requirement is satisfiable.
        vm.deal(address(c), 1 ether); // balance now exactly 2 ether

        // Move past the target block and settle.
        vm.roll(target + 1);
        vm.prank(actor);
        c.settle();

        // The correct guess always wins the whole prize: contract drained to 0.
        assertTrue(address(c).balance == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint256 seed, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(uint160(actor) > 100); // avoid precompiles/special addresses

        uint256 target = block.number + 1;
        bytes32 h = keccak256(abi.encodePacked(seed, actor));
        // In the reference, settle() computes keccak256(blockhash(target)); blockhash
        // returns 0 for any future/nonexistent block, so the answer the contract
        // will accept at settle time is deterministically this value:
        bytes32 answer = keccak256(abi.encodePacked(bytes32(0)));

        vm.roll(target - 1);
        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        // General rule: a locked-in guess is settled exactly when it equals the
        // settlement answer; when it matches, the prize is paid out.
        vm.roll(target + 1);
        vm.prank(actor);
        if (h == answer) {
            c.settle();
            assertTrue(address(c).balance == 0, "prize must be paid when guess equals answer");
        } else {
            c.settle();
            assertTrue(address(c).balance == 1 ether, "no prize when guess differs from answer");
        }
    }
}

