import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }
    function testFuzz_property(bytes32 guessHash, address actor) public {
        vm.assume(guessHash != bytes32(0));
        vm.assume(actor != address(0) && actor != address(c));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);

        uint target = c.guesses(actor).block;
        vm.roll(target + 1);

        vm.prank(actor);
        c.settle();

        bool paid = address(c).balance == 0;
        bytes32 expectedAnswer = keccak256(abi.encodePacked(blockhash(target)));
        assertTrue(paid == (guessHash == expectedAnswer));
    }
}

