pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 h) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // give c the full prize pot and give the actor the entry stake
        vm.deal(address(c), 2 ether);
        vm.deal(actor, 1 ether);

        // lock in the fuzzed hash; target block is the next one
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);
        uint256 target = block.number + 1;

        // move past the target block; blockhash(target) is 0 for foundry-managed blocks
        vm.roll(target + 1);
        bytes32 answer = keccak256(abi.encodePacked(blockhash(target)));

        vm.prank(actor);
        c.settle();

        // General rule: a correct contract stores the caller's hash, so a caller
        // whose stored hash equals the settlement answer wins the 2-ether prize
        // on settle, leaving c with zero balance. The mutant never stores the hash
        // (it stays bytes32(0)), so for h == answer it never pays and the balance
        // stays nonzero.
        assertTrue(h != answer || address(c).balance == 0);
    }
}

