pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint256 startBlock, bytes32 guess, address actor) public {
        vm.assume(actor != address(0));
        bound(startBlock, 1, type(uint256).max / 2);

        // lock a guess at an arbitrary fuzzed block
        vm.roll(startBlock);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // settle in the very next block: must still revert, because the
        // stored target block (lock block + 1) is not yet in the past
        vm.roll(startBlock + 1);
        vm.prank(actor);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }

        assertTrue(!ok, "settle must revert when target block not yet passed");
    }
}

