pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 seed) public {
        vm.assume(actor != address(0) && actor != address(c));

        uint256 b = block.number; // lockInGuess will target block b+1
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(keccak(abi.encodePacked(seed)));

        // settle must happen at a block strictly greater than the target block b+1
        vm.roll(b + 2);
        vm.prank(actor);
        c.settle();

        // In the reference contract the answer is keccak(blockhash(b+1)); the payout of
        // 2 ether can only occur when seed == blockhash(b+1). Otherwise the contract
        // must still hold its full 2 ether.
        assertTrue(
            blockhash(b + 1) == seed || address(c).balance == 2 ether,
            "settle paid without a genuine winning guess"
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test() public {
        bool ok;
        (ok, ) = address(c).call(abi.encodeWithSignature("settle()"));
        assert(!ok);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function testLockInGuessValue(uint256 amount) public {
        require(address(this).balance >= amount);
        bool reverted = false;
        bytes32 g = keccak256(abi.encodePacked(uint256(1)));
        if (amount == 1 ether) {
            c.lockInGuess{value: amount}(g);
        } else {
            try c.lockInGuess{value: amount}(g) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }
        assert(reverted == (amount != 1 ether));
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        require(amount == 0);
        bool reverted;
        try c.settle() { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

