contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.lockInGuess(keccak256(abi.encodePacked(block.number))) { reverted = false; } catch { reverted = true; }
        // On P, lockInGuess only succeeds when exactly 1 ether is attached;
        // on M it succeeds for any value, violating the rule below.
        assert(reverted || amount == 1 ether);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        require(true);
        bool r1;
        try c.settle() { r1 = false; } catch { r1 = true; }
        bool r2;
        try c.settle() { r2 = false; } catch { r2 = true; }
        assert(r1 && r2);
    }
    receive() external payable {}
}
